<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { storeToRefs } from "pinia";
import { useShellStore } from "@/app/shellStore";
import { usePayrollStore } from "../stores/payrollStore";
import type { DutyLogPayrollDomain, PayrollCompensationTermInput } from "../types/domain";
import { navigateHashRoute } from "@/platform/router/hashRoute";
import PricingSettingsCard from "./PricingSettingsCard.vue";
import CompensationComponentsCard from "./CompensationComponentsCard.vue";

const shell = useShellStore(); const store = usePayrollStore();
const { activeRoute, language, modulesLoaded, modules } = storeToRefs(shell); const { period, loading, error } = storeToRefs(store);
let previousDomain: DutyLogPayrollDomain | undefined;
function defaultMonth(): string { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`; }
const month = ref(defaultMonth()); const effectiveMonth = ref(defaultMonth());
const payMode = ref<"HOURLY"|"SALARY">("HOURLY"); const currencyCode = ref("RUB"); const compensationAmount = ref("");
const adjustmentType = ref<"ADDITION"|"DEDUCTION">("ADDITION"); const adjustmentAmount = ref("");
const adjustmentTitle = ref(""); const adjustmentNote = ref(""); const message = ref(""); const messageOk = ref(false);
const payrollEnabled = computed(() => modulesLoaded.value && modules.value.payroll !== false);
const preview = computed(() => period.value?.preview ?? null); const productionCalendar = computed(() => period.value?.productionCalendar ?? null);
const productionAffectedDays = computed(() => productionCalendar.value?.days.filter(day => day.sourceType !== "NONE") ?? []);
const effectiveCompensation = computed(() => period.value?.effectiveCompensation ?? null);
const compensationHistory = computed(() => period.value?.compensationHistory ?? []);
const currency = computed(() => preview.value?.currencyCode || effectiveCompensation.value?.currencyCode || period.value?.settings.currencyCode || "RUB");
const salaryMode = computed(() => preview.value?.payMode === "SALARY");

const text = computed(() => language.value === "en" ? {
  foundation:"Native Payroll",title:"Payroll",intro:"Tell DutyLog how you are paid once. Day Truth supplies time; Payroll turns canonical time and explicit settlements into money.",month:"Accounting month",reload:"Refresh",period:"Period",periodClosed:"Period is closed",periodOpen:"Period is open",frozen:"The time source is frozen",live:"Preview changes with Day Truth",integrity:"Integrity",healthy:"Ledger is healthy",unhealthy:"Ledger has issues",payable:"Payroll result",totalPay:"Total payable",preview:"Preview",revision:"Revision",breakdown:"Time behind the amount",planned:"Required norm",worked:"Worked",paidAbsence:"Paid absence",unpaid:"Unpaid time",timeAdjustment:"Time adjustment",payableTime:"Canonical payable time",ordinaryBaseTime:"Ordinary base time",setup:"How are you paid?",hourly:"Hourly rate",salary:"Monthly salary",effective:"Effective from month",currencyCode:"Currency",amount:"Amount",save:"Save compensation",history:"Compensation history",remove:"Delete",salaryHint:"Salary covers the required norm according to coverage. Explicit overtime cash settlements are added separately.",hourlyHint:"Ordinary hourly base excludes banked overtime. Overtime becomes money only through an explicit cash settlement.",effectiveRate:"Effective hourly value",coverage:"Salary-covered norm",basePay:"Ordinary base pay",ordinaryPremium:"Night / holiday premium",settlement:"Overtime settlement",settlementTransactions:"Settlement transactions",settlementBase:"Settlement base",settlementPremium:"Settlement premiums",settlementTotal:"Overtime paid",settlementReady:"Settlement pricing is ready",settlementNone:"No overtime cash settlements in this payroll month",settlementProvenanceBlock:"Some settled overtime minutes have no canonical provenance, so DutyLog cannot price them automatically.",settlementRulesBlock:"Pricing rules are missing for the historical source date of part of this settlement.",settlementCurrencyBlock:"Historical settlement sources resolve to incompatible currencies.",settlementPayrollCurrencyBlock:"The overtime settlement currency does not match this payroll month's compensation currency.",settlementGenericBlock:"Overtime settlement pricing is not ready.",technicalDetails:"Technical calculation identity",fingerprint:"Pricing fingerprint",additions:"Additions",deductions:"Deductions",manual:"Manual operations",operations:"Additions and deductions",addition:"Addition",deduction:"Deduction",titlePlaceholder:"For example: bonus",notePlaceholder:"Comment",addOperation:"Add operation",snapshots:"Closed calculation",revisions:"Snapshot revisions",calculate:"Save new revision",noAdjustments:"No manual adjustments",noSnapshots:"No calculations yet",periodOpenBlock:"Close the accounting period first",integrityBlock:"Fix ledger integrity issues first",compensationBlock:"Set how you are paid first",coverageBlock:"Salary mode needs complete schedule coverage for the month",normBlock:"Salary mode needs a positive production norm",ready:"Ready to calculate",included:"Included in salary base",loading:"Loading…",openCalendar:"Open calendar",production:"Production norm",base:"Base schedule norm",adjustment:"Calendar adjustment",rules:"Calendar rules",noRules:"No production-calendar rules",coverageWarn:"Schedule coverage is incomplete; norm uses known dates only.",saved:"Compensation saved",deleted:"Compensation term deleted",adjustmentOk:"Money adjustment added",calculateOk:"Payroll revision saved",invalidAmount:"Enter a positive amount",
} : {
  foundation:"Native Payroll",title:"Расчёт зарплаты",intro:"Один раз скажи DutyLog, как тебе платят. Время приходит из Day Truth, а Payroll переводит каноническое время и явные выплаты переработки в деньги.",month:"Расчётный месяц",reload:"Обновить",period:"Период",periodClosed:"Период закрыт",periodOpen:"Период открыт",frozen:"Источник времени зафиксирован",live:"Предпросмотр меняется вместе с Day Truth",integrity:"Целостность",healthy:"Журнал согласован",unhealthy:"Есть расхождения",payable:"Расчёт выплаты",totalPay:"Итого к выплате",preview:"Предпросмотр",revision:"Ревизия",breakdown:"Из какого времени получилась сумма",planned:"Обязательная норма",worked:"Фактически отработано",paidAbsence:"Оплачиваемые отсутствия",unpaid:"Неоплачиваемое время",timeAdjustment:"Корректировка времени",payableTime:"Каноническое оплачиваемое время",ordinaryBaseTime:"Время обычной оплаты",setup:"Как тебе платят?",hourly:"Почасовая ставка",salary:"Оклад",effective:"Действует с месяца",currencyCode:"Валюта",amount:"Сумма",save:"Сохранить условия",history:"История условий",remove:"Удалить",salaryHint:"Оклад покрывает обязательную норму согласно фактическому покрытию. Явные денежные выплаты переработки добавляются отдельно.",hourlyHint:"Обычная почасовая база не включает переработку, оставленную в банке. Она превращается в деньги только через явную выплату.",effectiveRate:"Расчётная стоимость часа",coverage:"Норма, покрытая окладом",basePay:"Обычная оплата",ordinaryPremium:"Ночная / праздничная доплата",settlement:"Выплата переработки",settlementTransactions:"Операций выплаты",settlementBase:"Базовая часть выплаты",settlementPremium:"Надбавки",settlementTotal:"Выплата за переработку",settlementReady:"Расчёт выплаты переработки готов",settlementNone:"В этом расчётном месяце нет денежных выплат переработки",settlementProvenanceBlock:"У части выплачиваемой переработки нет подтверждённого происхождения минут, поэтому DutyLog не может безопасно рассчитать её автоматически.",settlementRulesBlock:"Для исторической даты части выплачиваемой переработки не настроены правила оплаты.",settlementCurrencyBlock:"Исторические источники выплаты переработки рассчитаны в несовместимых валютах.",settlementPayrollCurrencyBlock:"Валюта выплаты переработки не совпадает с валютой этого расчётного месяца.",settlementGenericBlock:"Расчёт выплаты переработки пока недоступен.",technicalDetails:"Техническая идентичность расчёта",fingerprint:"Отпечаток pricing",additions:"Начисления",deductions:"Удержания",manual:"Ручные операции",operations:"Начисления и удержания",addition:"Начисление",deduction:"Удержание",titlePlaceholder:"Например: премия",notePlaceholder:"Комментарий",addOperation:"Добавить операцию",snapshots:"Закрытый расчёт",revisions:"Ревизии snapshot",calculate:"Зафиксировать новую ревизию",noAdjustments:"Нет ручных операций",noSnapshots:"Расчётов пока нет",periodOpenBlock:"Сначала закрой расчётный период",integrityBlock:"Сначала исправь расхождения журнала",compensationBlock:"Сначала укажи, как тебе платят",coverageBlock:"Для оклада сначала заполни график на весь расчётный месяц",normBlock:"Для оклада нужна положительная расчётная норма месяца",ready:"Готово к фиксации",included:"Входит в базовый оклад",loading:"Загрузка…",openCalendar:"Открыть календарь",production:"Расчётная норма",base:"Базовая норма графика",adjustment:"Корректировка календаря",rules:"Правила календаря",noRules:"В этом месяце правил производственного календаря нет",coverageWarn:"График заполнен не на весь месяц: норма считается по известным датам.",saved:"Условия оплаты сохранены",deleted:"Условия оплаты удалены",adjustmentOk:"Денежная операция добавлена",calculateOk:"Ревизия расчёта сохранена",invalidAmount:"Укажи положительную сумму",
});
function minutes(value:number|null|undefined):string { const total=Math.round(Number(value??0)), sign=total<0?"−":"", safe=Math.abs(total), h=Math.floor(safe/60), m=safe%60; return language.value==="en"?`${sign}${h} h${m?` ${m} min`:""}`:`${sign}${h} ч${m?` ${m} мин`:""}`; }
function money(minor:number|null|undefined, code=currency.value):string { const value=Number(minor??0)/100; try { return new Intl.NumberFormat(language.value==="en"?"en-US":"ru-RU",{style:"currency",currency:String(code||"RUB").toUpperCase(),minimumFractionDigits:2,maximumFractionDigits:2}).format(value); } catch { return `${value.toFixed(2)} ${code}`; } }
function moneyForMinutes(value:number|null|undefined, rate:number|null|undefined):number { return Math.round((Number(value??0)*Number(rate??0))/60); }
function compensationMonthLabel(value:string|null|undefined):string { if(value==="1970-01") return language.value==="en"?"Initial conditions":"Исходные условия"; return value||"—"; }
function requestErrorMessage(caught:unknown):string { return caught instanceof Error&&caught.message?caught.message:error.value||(language.value==="en"?"Request failed":"Не удалось выполнить запрос"); }
function settlementBlockingMessage(code:string|null|undefined):string {
  switch(code){
    case"PAY_PRICING_PROVENANCE_REQUIRED":return text.value.settlementProvenanceBlock;
    case"PAY_PRICING_RULES_REQUIRED":return text.value.settlementRulesBlock;
    case"PAY_PRICING_CURRENCY_MISMATCH":return text.value.settlementCurrencyBlock;
    case"PAYROLL_SETTLEMENT_CURRENCY_MISMATCH":return text.value.settlementPayrollCurrencyBlock;
    case"PAYROLL_COMPENSATION_REQUIRED":return text.value.compensationBlock;
    case"PAYROLL_PRODUCTION_NORM_INCOMPLETE":return text.value.coverageBlock;
    case"PAYROLL_PRODUCTION_NORM_REQUIRED":return text.value.normBlock;
    default:return code?text.value.settlementGenericBlock:"";
  }
}
const breakdown = computed(() => { const p=preview.value; if(!p)return []; const rows=[{key:"worked",label:text.value.worked,value:p.workedMinutes},{key:"vacation",label:language.value==="en"?"Paid vacation":"Оплачиваемый отпуск",value:p.vacationMinutes},{key:"sick",label:language.value==="en"?"Sick leave":"Больничный",value:p.sickMinutes},{key:"overtime",label:language.value==="en"?"Overtime time-off":"Отгул из переработок",value:p.overtimeCompensatedMinutes},{key:"adjustment",label:text.value.timeAdjustment,value:p.timeAdjustmentMinutes}].filter(i=>Number(i.value)!==0); return rows.map(i=>({...i,amount:salaryMode.value?null:moneyForMinutes(i.value,p.effectiveHourlyRateMinor)})); });
const settlementBlocking = computed(() => preview.value&&!preview.value.settlementPricingReady?settlementBlockingMessage(preview.value.settlementPricingBlockingReason):"");
const blocking = computed(() => {
  switch(period.value?.blockingReason){
    case"PERIOD_OPEN":return text.value.periodOpenBlock;
    case"LEDGER_INTEGRITY_FAILED":return text.value.integrityBlock;
    case"PAYROLL_COMPENSATION_REQUIRED":return text.value.compensationBlock;
    case"PAYROLL_PRODUCTION_NORM_INCOMPLETE":return text.value.coverageBlock;
    case"PAYROLL_PRODUCTION_NORM_REQUIRED":return text.value.normBlock;
    default:
      if(preview.value&&!preview.value.settlementPricingReady)return settlementBlockingMessage(period.value?.blockingReason);
      if(preview.value&&!preview.value.ordinaryPremiumPricingReady)return text.value.ordinaryPremium;
      return settlementBlockingMessage(period.value?.blockingReason);
  }
});
function synchronizeInputs():void { const term=effectiveCompensation.value; effectiveMonth.value=month.value; payMode.value=term?.payMode==="SALARY"?"SALARY":"HOURLY"; currencyCode.value=term?.currencyCode||period.value?.settings.currencyCode||"RUB"; const minor=payMode.value==="SALARY"?term?.monthlySalaryMinor:term?.hourlyRateMinor; compensationAmount.value=minor? (Number(minor)/100).toFixed(2):""; }
function openCalendar():void { navigateHashRoute("calendar"); }
async function refresh():Promise<void>{ if(!payrollEnabled.value)return; try{await store.load(month.value);synchronizeInputs();}catch(caught){message.value=requestErrorMessage(caught);messageOk.value=false;} }
async function saveCompensation():Promise<void>{ const amount=Number(compensationAmount.value); if(!Number.isFinite(amount)||amount<=0){message.value=text.value.invalidAmount;messageOk.value=false;return;} const body:PayrollCompensationTermInput={payMode:payMode.value,currencyCode:currencyCode.value.trim().toUpperCase()||"RUB",hourlyRateMinor:payMode.value==="HOURLY"?Math.round(amount*100):null,monthlySalaryMinor:payMode.value==="SALARY"?Math.round(amount*100):null}; try{await store.saveCompensationTerm(effectiveMonth.value,body);synchronizeInputs();message.value=text.value.saved;messageOk.value=true;}catch(caught){message.value=requestErrorMessage(caught);messageOk.value=false;} }
async function removeCompensation(termMonth:string):Promise<void>{ try{await store.deleteCompensationTerm(termMonth);synchronizeInputs();message.value=text.value.deleted;messageOk.value=true;}catch(caught){message.value=requestErrorMessage(caught);messageOk.value=false;} }
async function addAdjustment():Promise<void>{const amount=Number(adjustmentAmount.value);if(!Number.isFinite(amount)||amount<=0){message.value=text.value.invalidAmount;messageOk.value=false;return;}const title=adjustmentTitle.value.trim();if(!title){message.value=text.value.titlePlaceholder;messageOk.value=false;return;}try{await store.addAdjustment({month:month.value,adjustmentType:adjustmentType.value,amountMinor:Math.round(amount*100),title,note:adjustmentNote.value.trim()||null});adjustmentAmount.value="";adjustmentTitle.value="";adjustmentNote.value="";message.value=text.value.adjustmentOk;messageOk.value=true;}catch(caught){message.value=requestErrorMessage(caught);messageOk.value=false;}}
async function calculate():Promise<void>{try{await store.calculate();message.value=text.value.calculateOk;messageOk.value=true;}catch(caught){message.value=requestErrorMessage(caught);messageOk.value=false;}}
async function synchronizeRoute(route:string):Promise<void>{if(route==="payroll"&&payrollEnabled.value)await refresh();}
onMounted(()=>{previousDomain=window.DutyLogVueDomains?.payroll;const domain:DutyLogPayrollDomain=Object.freeze({ready:()=>store.loaded&&!store.loading,refresh});window.DutyLogVueDomains=Object.freeze({...(window.DutyLogVueDomains??{}),payroll:domain});document.documentElement.dataset.vuePayroll="ready";void synchronizeRoute(activeRoute.value);});
watch(activeRoute,route=>{void synchronizeRoute(route);});watch([modulesLoaded,modules],()=>{if(activeRoute.value==="payroll")void refresh();},{deep:true});watch(month,()=>{effectiveMonth.value=month.value;});
onBeforeUnmount(()=>{if(previousDomain)window.DutyLogVueDomains=Object.freeze({...(window.DutyLogVueDomains??{}),payroll:previousDomain});else if(window.DutyLogVueDomains){const{payroll:_removed,...rest}=window.DutyLogVueDomains;window.DutyLogVueDomains=Object.freeze(rest);}delete document.documentElement.dataset.vuePayroll;});
</script>

<template><section v-if="activeRoute === 'payroll'" id="view-payroll" class="view payrollView" data-vue-domain-route="payroll" data-vue-domain-owner="payroll"><div class="payrollWorkspace">
<header class="payrollHero card" aria-labelledby="payrollTitle"><div><div class="eyebrow">{{ text.foundation }}</div><h2 id="payrollTitle">{{ text.title }}</h2><p>{{ text.intro }}</p></div><div class="payrollHeroControls"><label>{{ text.month }}<input id="payrollMonth" v-model="month" type="month" @change="refresh"/></label><button id="payrollReload" type="button" :disabled="loading" @click="refresh">{{ text.reload }}</button></div></header>
<section class="payrollStatusRow" aria-label="Статус источника расчёта"><div class="payrollStatusCard"><span>{{ text.period }}</span><b id="payrollPeriodStatus" :class="period?.periodClosed?'ok':'warn'">{{ period?.periodClosed?text.periodClosed:text.periodOpen }}</b><small id="payrollPeriodHint">{{ period?.periodClosed?text.frozen:text.live }}</small></div><div class="payrollStatusCard"><span>{{ text.integrity }}</span><b id="payrollIntegrityStatus" :class="period?.integrityHealthy?'ok':'bad'">{{ period?.integrityHealthy?text.healthy:text.unhealthy }}</b></div><div class="payrollStatusCard total"><span>{{ text.totalPay }}</span><b id="payrollTotal">{{ money(preview?.totalPayMinor) }}</b><small id="payrollRevisionLabel">{{ period?.latestSnapshot?`${text.revision} ${period.latestSnapshot.revision} · ${money(period.latestSnapshot.totalPayMinor,period.latestSnapshot.currencyCode)}`:text.preview }}</small></div></section>

<div class="payrollGrid payrollCompensationGrid"><section class="card payrollSettingsCard payrollCompensationCard"><div class="payrollSectionHead"><div><div class="eyebrow">Compensation</div><h3>{{ text.setup }}</h3></div></div><form id="payrollSettingsForm" class="payrollSettingsForm nativeCompensationForm" @submit.prevent="saveCompensation"><div class="compensationModeSwitch"><button type="button" :class="{active:payMode==='HOURLY'}" @click="payMode='HOURLY'">{{ text.hourly }}</button><button type="button" :class="{active:payMode==='SALARY'}" @click="payMode='SALARY'">{{ text.salary }}</button></div><label>{{ text.effective }}<input id="payrollCompensationMonth" v-model="effectiveMonth" type="month" required/></label><label>{{ text.currencyCode }}<input id="payrollCurrency" v-model="currencyCode" maxlength="3" pattern="[A-Za-z]{3}" required/></label><label>{{ payMode==='SALARY'?text.salary:text.hourly }}<input id="payrollHourlyRate" v-model="compensationAmount" type="number" min="0.01" max="10000000000" step="0.01" required/></label><button class="primary" type="submit" :disabled="loading">{{ text.save }}</button></form><p class="payrollHint">{{ payMode==='SALARY'?text.salaryHint:text.hourlyHint }}</p>
<div v-if="compensationHistory.length" class="compensationHistory"><div class="eyebrow">{{ text.history }}</div><article v-for="item in compensationHistory" :key="item.id" class="compensationHistoryRow"><span><b>{{ compensationMonthLabel(item.effectiveMonth) }} · {{ item.payMode==='SALARY'?text.salary:text.hourly }}</b><small>{{ item.payMode==='SALARY'?money(item.monthlySalaryMinor,item.currencyCode):`${money(item.hourlyRateMinor,item.currencyCode)} / ч` }}</small></span><button v-if="item.effectiveMonth !== '1970-01'" type="button" :disabled="loading" @click="removeCompensation(item.effectiveMonth)">{{ text.remove }}</button></article></div></section>
<section class="card payrollMoneyCard"><div class="payrollSectionHead"><div><div class="eyebrow">{{ preview?.payMode || '—' }}</div><h3>{{ text.payable }}</h3></div><span id="payrollCurrencyBadge">{{ currency }}</span></div><div class="payrollMoneySummary nativePayrollSummary"><div v-if="preview?.payMode==='SALARY'"><span>{{ text.salary }}</span><b>{{ money(preview?.monthlySalaryMinor) }}</b></div><div><span>{{ text.production }}</span><b>{{ minutes(preview?.productionNormMinutes) }}</b></div><div><span>{{ text.effectiveRate }}</span><b>{{ money(preview?.effectiveHourlyRateMinor) }} / ч</b></div><div v-if="preview?.payMode==='SALARY'"><span>{{ text.coverage }}</span><b>{{ minutes(preview?.salaryCoveredMinutes) }} / {{ minutes(preview?.productionNormMinutes) }}</b></div><div v-if="preview?.payMode==='HOURLY'"><span>{{ text.ordinaryBaseTime }}</span><b id="payrollHourlyBasePayable">{{ minutes(preview?.hourlyBasePayableMinutes) }}</b></div><div><span>{{ text.basePay }}</span><b id="payrollBasePay">{{ money(preview?.basePayMinor) }}</b></div></div><div v-if="preview&&(!preview.ordinaryPremiumPricingReady||preview.ordinaryPremiumPricingIdentityRequired||preview.ordinaryPremiumPayMinor)" class="payrollBreakdown" id="payrollOrdinaryPremiumBreakdown"><div class="payrollBreakdownRow"><span><b>{{ text.ordinaryPremium }}</b><small>{{ minutes(preview.ordinaryPremiumMinutes) }} · {{ text.basePay }}: {{ money(preview.ordinaryPremiumReferenceBasePayMinor) }}</small></span><strong id="payrollOrdinaryPremium">{{ money(preview.ordinaryPremiumPayMinor) }}</strong></div></div><div class="payrollBreakdown payrollSettlementBreakdown" id="payrollSettlementBreakdown"><div class="payrollBreakdownRow"><span><b>{{ text.settlement }}</b><small v-if="preview?.settlementCount">{{ text.settlementTransactions }}: {{ preview.settlementCount }} · {{ minutes(preview.settlementMinutes) }}</small><small v-else>{{ text.settlementNone }}</small></span><strong id="payrollSettlementTotal">{{ money(preview?.settlementPayMinor) }}</strong></div><div v-if="preview?.settlementCount" class="payrollBreakdownRow"><span><b>{{ text.settlementBase }}</b><small>{{ minutes(preview.settlementMinutes) }}</small></span><strong id="payrollSettlementBase">{{ money(preview.settlementBasePayMinor) }}</strong></div><div v-if="preview?.settlementCount" class="payrollBreakdownRow"><span><b>{{ text.settlementPremium }}</b></span><strong id="payrollSettlementPremium">{{ money(preview.settlementPremiumPayMinor) }}</strong></div></div><div v-if="preview&&!preview.settlementPricingReady" id="payrollSettlementPricingStatus" class="payrollBlocking blocked">{{ settlementBlocking || text.settlementGenericBlock }}</div><div v-else-if="preview?.settlementCount" id="payrollSettlementPricingStatus" class="payrollBlocking ready">{{ text.settlementReady }}</div><div class="payrollMoneySummary nativePayrollSummary"><div><span>{{ text.additions }}</span><b id="payrollAdditions">{{ money(preview?.additionsMinor) }}</b></div><div><span>{{ text.deductions }}</span><b id="payrollDeductions">{{ money(preview?.deductionsMinor) }}</b></div><div class="accent"><span>{{ text.totalPay }}</span><b id="payrollGrandTotal">{{ money(preview?.totalPayMinor) }}</b></div></div></section></div>

<CompensationComponentsCard
  :language="language"
  :month="month"
  :currency-code="currency"
/>

<PricingSettingsCard :language="language" />

<section class="card productionCalendarCard" data-production-calendar-foundation><div class="payrollSectionHead"><div><div class="eyebrow">Production Calendar</div><h3>{{ text.production }}</h3></div><button type="button" @click="openCalendar">{{ text.openCalendar }}</button></div><div class="productionNormMetrics"><div><span>{{ text.base }}</span><b id="productionBaseNorm">{{ minutes(productionCalendar?.baseNormMinutes) }}</b></div><div><span>{{ text.adjustment }}</span><b id="productionNormAdjustment">{{ minutes(productionCalendar?.adjustmentMinutes) }}</b></div><div class="accent"><span>{{ text.production }}</span><b id="productionNorm">{{ minutes(productionCalendar?.productionNormMinutes) }}</b></div></div><p v-if="productionCalendar&&!productionCalendar.scheduleCoverageComplete" id="productionCoverageWarning" class="productionCoverageWarning">{{ text.coverageWarn }}</p><div class="productionCalendarRules" data-production-calendar-summary-only><article v-for="day in productionAffectedDays" :key="day.date" class="productionCalendarRule productionCalendarRule--summary"><span><b>{{ day.date }}</b><small>{{ day.label || day.dayKind }}</small></span><strong>{{ minutes(day.baseNormMinutes) }} → {{ minutes(day.productionNormMinutes) }}</strong></article><div v-if="!productionAffectedDays.length" class="payrollEmpty">{{ text.noRules }}</div></div></section>

<div class="payrollGrid"><section class="card payrollSummaryCard"><div class="payrollSectionHead"><div><div class="eyebrow">Day Truth → Payroll</div><h3>{{ text.breakdown }}</h3></div></div><div class="payrollMetricGrid"><div><span>{{ text.planned }}</span><b id="payrollPlanned">{{ minutes(preview?.plannedMinutes) }}</b></div><div><span>{{ text.worked }}</span><b id="payrollWorked">{{ minutes(preview?.workedMinutes) }}</b></div><div><span>{{ text.paidAbsence }}</span><b id="payrollPaidAbsence">{{ minutes(preview?.paidAbsenceMinutes) }}</b></div><div><span>{{ text.unpaid }}</span><b id="payrollUnpaid">{{ minutes(preview?.unpaidMinutes) }}</b></div><div><span>{{ text.timeAdjustment }}</span><b id="payrollTimeAdjustment">{{ minutes(preview?.timeAdjustmentMinutes) }}</b></div><div><span>{{ text.payableTime }}</span><b id="payrollPayable">{{ minutes(preview?.payableMinutes) }}</b></div><div v-if="preview?.payMode==='HOURLY'" class="accent"><span>{{ text.ordinaryBaseTime }}</span><b id="payrollHourlyBaseMinutes">{{ minutes(preview?.hourlyBasePayableMinutes) }}</b></div></div><div class="payrollBreakdown" id="payrollBreakdown"><div v-for="item in breakdown" :key="item.key" class="payrollBreakdownRow"><span><b>{{ item.label }}</b><small>{{ minutes(item.value) }}</small></span><strong>{{ item.amount===null?text.included:money(item.amount) }}</strong></div></div></section>
<section class="card payrollSnapshotCard"><div class="payrollSectionHead"><div><div class="eyebrow">{{ text.snapshots }}</div><h3>{{ text.revisions }}</h3></div></div><div class="payrollBlocking" id="payrollBlocking" :class="blocking?'blocked':'ready'">{{ blocking || text.ready }}</div><button class="primary payrollCalculate" id="payrollCalculate" type="button" :disabled="!period?.canCalculate||loading" @click="calculate">{{ text.calculate }}</button><div class="payrollSnapshotList" id="payrollSnapshotList"><article v-for="item in period?.snapshots??[]" :key="item.id" class="payrollSnapshotItem" :class="item.supersededById?'superseded':'current'"><span><b>{{ text.revision }} {{ item.revision }}</b><small>{{ item.payMode }} · {{ compensationMonthLabel(item.compensationEffectiveMonth) }} · {{ new Date(item.createdAt).toLocaleString(language==='en'?'en-US':'ru-RU') }}</small><small v-if="item.settlementCount">{{ text.settlement }} · {{ minutes(item.settlementMinutes) }} · {{ money(item.settlementPayMinor,item.currencyCode) }}</small><small v-if="item.ordinaryPremiumPricingFingerprint">{{ text.ordinaryPremium }} · {{ minutes(item.ordinaryPremiumMinutes) }} · {{ money(item.ordinaryPremiumPayMinor,item.currencyCode) }}</small><details v-if="item.settlementPricingFingerprint" class="payrollSnapshotTechnical"><summary>{{ text.technicalDetails }}</summary><small>{{ text.fingerprint }}</small><code class="payrollFingerprint">{{ item.settlementPricingFingerprint }}</code></details></span><strong>{{ money(item.totalPayMinor,item.currencyCode) }}</strong></article><div v-if="!(period?.snapshots.length)" class="payrollEmpty">{{ text.noSnapshots }}</div></div></section></div>

<section class="card payrollAdjustmentsCard"><div class="payrollSectionHead"><div><div class="eyebrow">{{ text.manual }}</div><h3>{{ text.operations }}</h3></div></div><form id="payrollAdjustmentForm" class="payrollAdjustmentForm" @submit.prevent="addAdjustment"><select id="payrollAdjustmentType" v-model="adjustmentType" :disabled="!period?.periodClosed||loading"><option value="ADDITION">{{ text.addition }}</option><option value="DEDUCTION">{{ text.deduction }}</option></select><input id="payrollAdjustmentAmount" v-model="adjustmentAmount" type="number" min="0.01" step="0.01" :placeholder="text.amount" required :disabled="!period?.periodClosed||loading"/><input id="payrollAdjustmentTitle" v-model="adjustmentTitle" maxlength="120" :placeholder="text.titlePlaceholder" required :disabled="!period?.periodClosed||loading"/><input id="payrollAdjustmentNote" v-model="adjustmentNote" maxlength="500" :placeholder="text.notePlaceholder" :disabled="!period?.periodClosed||loading"/><button type="submit" :disabled="!period?.periodClosed||loading">{{ text.addOperation }}</button></form><div class="payrollAdjustmentList" id="payrollAdjustmentList"><article v-for="item in period?.adjustments??[]" :key="item.id" class="payrollAdjustmentItem" :class="item.adjustmentType==='DEDUCTION'?'deduction':'addition'"><span><b>{{ item.title }}</b><small>{{ item.note || (item.adjustmentType==='DEDUCTION'?text.deduction:text.addition) }}</small></span><strong>{{ item.adjustmentType==='DEDUCTION'?'−':'+' }}{{ money(item.amountMinor) }}</strong></article><div v-if="!(period?.adjustments.length)" class="payrollEmpty">{{ text.noAdjustments }}</div></div></section>
<div class="appModalMessage payrollMessage" id="payrollMessage" :class="message?(messageOk?'ok':'err'):''" role="status" aria-live="polite">{{ message || (loading?text.loading:error) }}</div>
</div></section></template>

<style scoped>
.payrollFingerprint {
  display: block;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-size: 0.75rem;
}
.payrollSnapshotTechnical {
  margin-top: 0.35rem;
}
</style>
